mapper.insert:
/* NotificationMapper.insert */
INSERT INTO notification (user_no, category, event_code, content, link, created_at)
VALUES (#{userNo}, #{category}, #{eventCode}, #{content}, #{link}, #{createdAt})

mapper.select:
/* NotificationMapper.findByUserNoWithCursor */
SELECT 
FROM notification

    user_no = #{userNo}

        AND notification_id < #{cursor}


        AND category = #{category}


ORDER BY notification_id DESC
LIMIT #{size}

/* NotificationMapper.countUnread */
SELECT COUNT(*)
FROM notification
WHERE user_no = #{userNo}
  AND read_at IS NULL

mapper.update:
/* NotificationMapper.markAsRead */
UPDATE notification
SET read_at = NOW()
WHERE notification_id = #{notificationId}
  AND user_no = #{userNo}
  AND read_at IS NULL

/* NotificationMapper.markAllAsRead */
UPDATE notification
SET read_at = NOW()
WHERE user_no = #{userNo}
  AND read_at IS NULL

mapper.delete:
/* NotificationMapper.deleteOlderThan */
DELETE FROM notification
WHERE created_at < NOW() - INTERVAL #{days} DAY
